package android.widget;
import android.app.PendingIntent; import android.content.Intent; import java.util.*;
public class RemoteViews { public final String pkg; public final int layout; public RemoteViews(String p,int l){pkg=p;layout=l;}
 public Map<Integer,CharSequence> texts=new LinkedHashMap<>(); public Map<Integer,Intent> fills=new LinkedHashMap<>(); public Map<Integer,Integer> vis=new LinkedHashMap<>(); public Map<Integer,List<RemoteViews>> kids=new LinkedHashMap<>(); public Intent adapter; public PendingIntent template; public int scroll=-1;
 public void setTextViewText(int id,CharSequence t){texts.put(id,t);} public void setTextColor(int id,int c){} public void setTextViewTextSize(int id,int unit,float sz){} public Map<String,Integer> ints=new LinkedHashMap<>(); public void setInt(int id,String m,int v){ints.put(id+":"+m,v);} public void setViewVisibility(int id,int v){vis.put(id,v);}
 public Map<Integer,PendingIntent> clicks=new LinkedHashMap<>(); public void setOnClickPendingIntent(int id,PendingIntent p){clicks.put(id,p);} public void setOnClickFillInIntent(int id,Intent i){fills.put(id,i);} public void setProgressBar(int id,int max,int p,boolean ind){}
 public Map<Integer,Integer> imgs=new LinkedHashMap<>(); public void setImageViewResource(int id,int r){imgs.put(id,r);} public void setRemoteAdapter(int id,Intent i){adapter=i;} public void setPendingIntentTemplate(int id,PendingIntent p){template=p;}
 public void addView(int id,RemoteViews v){kids.computeIfAbsent(id,k->new ArrayList<>()).add(v);} public void removeAllViews(int id){kids.remove(id);} public void setScrollPosition(int id,int pos){scroll=pos;} public Map<Integer,Float> heights=new LinkedHashMap<>(); public void setViewLayoutHeight(int id,float h,int unit){heights.put(id,h);}  public Map<Integer,RemoteCollectionItems> lists=new LinkedHashMap<>(); public void setRemoteAdapter(int id,RemoteCollectionItems it){lists.put(id,it);}
 public static final class RemoteCollectionItems { public final List<Long> ids=new ArrayList<>(); public final List<RemoteViews> views=new ArrayList<>(); public boolean stable; public int types;
  public static final class Builder { RemoteCollectionItems it=new RemoteCollectionItems(); public Builder addItem(long id,RemoteViews v){it.ids.add(id);it.views.add(v);return this;} public Builder setHasStableIds(boolean b){it.stable=b;return this;} public Builder setViewTypeCount(int n){it.types=n;return this;}
   public RemoteCollectionItems build(){ Set<Integer> l=new HashSet<>(); for(RemoteViews v:it.views) l.add(v.layout); if(l.size()>it.types) throw new IllegalArgumentException("more layouts than view types"); return it; } } }
}
